parameters.jsCode:
const order = $input.first().json.body || $input.first().json;

let phone = order.phone 
  || order.shipping_address?.phone 
  || order.billing_address?.phone 
  || order.customer?.phone 
  || '';

phone = phone.replace(/[\s\-\+\(\)]/g, '');
if (phone.startsWith('0')) phone = '92' + phone.slice(1);
if (!phone.startsWith('92')) phone = '92' + phone;

const items = (order.line_items || [])
  .map(i => `• ${i.title} x${i.quantity} — PKR ${i.price}`)
  .join('\n');

const address = order.shipping_address 
  ? `${order.shipping_address.address1 || ''}, ${order.shipping_address.city || ''}, ${order.shipping_address.province || ''} ${order.shipping_address.zip || ''}`.trim()
  : 'Not provided';

const customerName = `${order.shipping_address?.first_name || order.customer?.first_name || ''} ${order.shipping_address?.last_name || order.customer?.last_name || ''}`.trim();

const paymentMethod = order.payment_gateway_names?.[0] || order.gateway || 'COD';
const isBankTransfer = paymentMethod.toLowerCase().includes('bank') || paymentMethod.toLowerCase().includes('transfer');

let messageText = `Assalam o Alaikum ${customerName}! 🛒\n\n📦 *Order #${order.order_number || order.name || ''}*\n\n${items}\n\n💰 Subtotal: PKR ${order.subtotal_price || '0'}\n🚚 Shipping: PKR ${order.total_shipping_price_set?.shop_money?.amount || '0'}\n*Total: PKR ${order.total_price || '0'}*\n\n📍 Address: ${address}\n💳 Payment: ${isBankTransfer ? 'Bank Transfer' : 'Cash on Delivery (COD)'}`;

if (isBankTransfer) {
  messageText += `\n\n🏦 Please transfer to:\nBank: MCB Limited\nAccount: REDACTED\nIBAN: REDACTED\nTitle: REDACTED\n\n📸 After transfer, please share the receipt screenshot here.`;
}

messageText += `\n\nReply *YES* to confirm or *NO* to cancel.\n\n— Walton Market`;

return [{
  json: {
    shopify_order_id: order.id?.toString() || '',
    order_number: order.order_number?.toString() || order.name || '',
    customer_name: customerName,
    customer_phone: phone,
    customer_email: order.customer?.email || order.email || '',
    chat_id: phone + '@c.us',
    items: items,
    total_price: order.total_price || '0',
    subtotal: order.subtotal_price || '0',
    shipping_cost: order.total_shipping_price_set?.shop_money?.amount || '0',
    currency: order.currency || 'PKR',
    address: address,
    payment_method: paymentMethod,
    is_bank_transfer: isBankTransfer,
    financial_status: order.financial_status || 'pending',
    created_at: order.created_at || new Date().toISOString(),
    message_text: messageText
  }
}];

const wahaResponse = $('Send WhatsApp via WAHA').first().json;
const orderData = $('Extract Order Data').first().json;

// Get the actual chat_id WAHA delivered to
const actualChatId = wahaResponse._data?.remote 
  || wahaResponse.to?._serialized 
  || wahaResponse.to 
  || orderData.chat_id;

return [{
  json: {
    shopify_order_id: orderData.shopify_order_id,
    actual_chat_id: actualChatId
  }
}];

parameters.query:
UPDATE orders 
SET whatsapp_chat_id = '{{ $json.actual_chat_id }}'
WHERE shopify_order_id = '{{ $json.shopify_order_id }}';
